SELECT MONTH_PLAN_VERSION
FROM T_DP_ORDER_OFFSET_DETAIL
WHERE FACTORY_CODE = #{factoryCode}
  AND YEAR = #{year}
  AND MONTH = #{month}
  AND IS_DELETE = 0
GROUP BY MONTH_PLAN_VERSION
ORDER BY MAX(CREATE_TIME) DESC
